function draw() {
  ctx.clearRect(0, 0, width, height);

  // Define center points
  const cx = width / 2;
  const cy = height / 2;
  const size = 240; // Half-width/height of the triangle

  ctx.fillStyle = 'rgb(255, 255, 100)'; // Yellow
  ctx.beginPath();

  // 1. Move to the Peak (Top Center)
  // To be "upright", the Y value must be LESS than the center
  ctx.moveTo(cx, cy - size); 

  // 2. Draw to Bottom Right
  ctx.lineTo(cx + size, cy + size);

  // 3. Draw to Bottom Left
  ctx.lineTo(cx - size, cy + size);

  ctx.closePath();
  ctx.fill();

  requestAnimationFrame(draw);
}

draw();

