tm.setup(() => {
  tm.fontSize(16)
  tm.frameRate(60)
})

tm.draw(() => {
  tm.background(0, 0, 0, 1)

  // Center coordinates
  const centerX = Math.floor(tm.grid.cols / 2)
  const centerY = Math.floor(tm.grid.rows / 2)
  const size = 12 // Scale of the triangle

  for (let y = 0; y < tm.grid.rows; y++) {
    for (let x = 0; x < tm.grid.cols; x++) {

      // Normalize coordinates relative to the center
      // nx and ny will be 0 at the middle of the screen
      const nx = x - centerX
      const ny = y - centerY

      // TRIANGLE LOGIC:
      // We define a top boundary (-size) and bottom boundary (size)
      // As ny increases (moves down), the allowed width increases.
      let mask = false
      if (ny > -size && ny < size) {
        // This math mirrors the GLSL: width gets smaller as ny gets smaller (closer to the tip)
        const width = (ny + size) * 0.6 
        if (Math.abs(nx) < width) {
          mask = true
        }
      }

      if (mask) {
        tm.push()
        tm.translate(nx, ny) // Using the center-offset translation from your template
        tm.char('█')
        tm.charColor(255, 255, 100) // Yellow
        tm.point()
        tm.pop()
      }
    }
  }
})
